import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/getting-started.md","filePath":"zh/manual/getting-started.md"}'),p={name:"zh/manual/getting-started.md"};function i(l,a,o,c,d,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><h2 id="启动-iso" tabindex="-1">启动 ISO <a class="header-anchor" href="#启动-iso" aria-label="Permalink to &quot;启动 ISO&quot;">​</a></h2><p>最快的路径是用 QEMU 运行发布 ISO：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512M -cdrom opencube-3.0.0.iso -boot d \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>加 <code>-vga std</code> 可获得图形控制台（TUI 桌面需要它），或用 <code>-display none -serial mon:stdio</code> 以无头模式运行。在 UEFI 主机上再加 <code>-bios OVMF.fd</code>（见 <a href="./boot-modes.html">boot-modes</a>）。</p><p>启动自检运行完毕，随后 ring-3 shell 与你见面：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Open Cube OS User-space Shell (3.0.0)</span></span>
<span class="line"><span>ush&gt;</span></span></code></pre></div><h2 id="头五分钟" tabindex="-1">头五分钟 <a class="header-anchor" href="#头五分钟" aria-label="Permalink to &quot;头五分钟&quot;">​</a></h2><p>8 个大应用是预期的操作面——从一个向导开始，看它干活：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo            what hardware is in this machine</span></span>
<span class="line"><span>ush&gt; sysdiag           health snapshot, kernel log, memory picture</span></span>
<span class="line"><span>ush&gt; net-tool          address setup, WiFi scan, connectivity tests</span></span>
<span class="line"><span>ush&gt; update            the 5-step OTA wizard (network -&gt; A/B -&gt; DNS</span></span>
<span class="line"><span>                        -&gt; check -&gt; install)</span></span></code></pre></div><p>按数字键选择菜单项，<code>q</code> 退出。破坏性路径会要求你重新输入目标名称，并回答一个单独的 <code>y</code>。</p><p>两个快速的只读导览：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool             disks, partitions, mounts</span></span>
<span class="line"><span>ush&gt; files                 browse, copy, edit</span></span></code></pre></div><h2 id="经典命令依然可用" tabindex="-1">经典命令依然可用 <a class="header-anchor" href="#经典命令依然可用" aria-label="Permalink to &quot;经典命令依然可用&quot;">​</a></h2><p>每条历史命令都保持注册——接口冻结规则保证了这一点（命令只增不删；注册表收录 284 个程序）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lsblk                 same service call as disk-tool lsblk</span></span>
<span class="line"><span>ush&gt; checkupdate           same as update&#39;s step 4</span></span>
<span class="line"><span>ush&gt; help                  shell built-ins + registry summary</span></span>
<span class="line"><span>ush&gt; help -a               every registry entry, A-Z, tagged</span></span>
<span class="line"><span>ush&gt; help -w               grouped by domain (the mega group first)</span></span></code></pre></div><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; files                 the wizard: ls / tree / df+du / cp / mv /</span></span>
<span class="line"><span>                            rm / edit / stat+chmod</span></span>
<span class="line"><span>ush&gt; files edit /etc/opencube.conf      the full-screen editor</span></span>
<span class="line"><span>ush&gt; cat /etc/opencube.conf              quick read</span></span>
<span class="line"><span>ush&gt; cd /etc &amp;&amp; ls</span></span></code></pre></div><p>ISO 从 RAM 运行（ramfs 根）；接入一块磁盘并用 <code>disk-tool</code> 分区 + 格式化 + 挂载即可获得持久化（见 <a href="./filesystems.html">filesystems</a>）。</p><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><p>使用上面的用户态网卡时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dhcp                  or net-tool -&gt; &quot;obtain an address via DHCP&quot;</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2         the QEMU gateway</span></span>
<span class="line"><span>ush&gt; dns example.com</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /</span></span></code></pre></div><p>TLS 与 SSH 均为内置：<code>wget</code> 协商 HTTPS，<code>sshd</code> 提供 shell 服务，<code>ssh</code> 向外连接（见 <a href="./network.html">network</a>）。</p><h2 id="关机" tabindex="-1">关机 <a class="header-anchor" href="#关机" aria-label="Permalink to &quot;关机&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; power                 the wizard (confirmed shutdown/reboot)</span></span>
<span class="line"><span>ush&gt; poweroff              the classic one-shot</span></span></code></pre></div><h2 id="接下来去哪里" tabindex="-1">接下来去哪里 <a class="header-anchor" href="#接下来去哪里" aria-label="Permalink to &quot;接下来去哪里&quot;">​</a></h2><ul><li><a href="./mega-apps.html">mega-apps</a>——向导 / direct / classic 契约</li><li><a href="./shell-basics.html">shell-basics</a>——管道、重定向、脚本</li><li><a href="./update-ota.html">update-ota</a>——更新向导与 A/B 机制</li><li><a href="./chinese-console.html">chinese-console</a>——<code>lang zh</code> 与输入法</li></ul>`,27)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
